package com.payshield.api; import com.payshield.domain.LedgerEntry; import java.math.BigDecimal; import java.time.Instant; public record LedgerResponse(String entryType,String account,BigDecimal amount,String currency,Instant createdAt){public static LedgerResponse from(LedgerEntry e){return new LedgerResponse(e.getEntryType(),e.getAccount(),e.getAmount(),e.getCurrency(),e.getCreatedAt());}}
